import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.BSwSpTvy.js";const r="/zed-custom/demo-search.gif",p=JSON.parse('{"title":"🌐 Headless Chromium Search","description":"","frontmatter":{},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md"}'),n={name:"features/search.md"};function c(i,e,d,h,l,m){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="🌐-headless-chromium-search" tabindex="-1">🌐 Headless Chromium Search <a class="header-anchor" href="#🌐-headless-chromium-search" aria-label="Permalink to &quot;🌐 Headless Chromium Search&quot;">​</a></h1><p>The ultimate AI assistant shouldn&#39;t just know your code; it should be able to read external documentation.</p><p>This custom fork integrates a full headless Chrome engine (<code>chromiumoxide</code>), seamlessly hooked into a new <code>/search</code> panel command.</p><h2 id="the-search-command" tabindex="-1">The <code>/search</code> Command <a class="header-anchor" href="#the-search-command" aria-label="Permalink to &quot;The `/search` Command&quot;">​</a></h2><p>By typing <code>/search &lt;query&gt;</code> into the Assistant Panel, you trigger an asynchronous background task that boots a headless Chromium instance, performs a DuckDuckGo search, navigates to the top URLs, and executes JavaScript to render SPA applications (like React or Vue docs).</p><p>Once the page is rendered, Zed extracts the Markdown payload and synthesizes a perfect answer for you, right inline with your current code.</p><p><img src="'+r+'" alt="Search Tool Demo"></p><h3 id="key-advantages" tabindex="-1">Key Advantages <a class="header-anchor" href="#key-advantages" aria-label="Permalink to &quot;Key Advantages&quot;">​</a></h3><ul><li><strong>No API Keys Needed</strong>: Unlike third-party search APIs, this uses a local Chromium instance to scrape open web results for free.</li><li><strong>JavaScript Rendering</strong>: Traditional scrapers fail on modern documentation sites. Headless Chrome ensures even the heaviest React apps are fully rendered before extraction.</li><li><strong>Deep Dives via <code>@fetch</code></strong>: You can explicitly command the agent to read specific pages by typing <code>@fetch https://example.com/docs</code>, embedding entire remote pages into your prompt window instantly.</li></ul>',9)])])}const g=a(n,[["render",c]]);export{p as __pageData,g as default};
